INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5238128, 762621, 49954, '<td valign="top">Wow... glad I didn''t find our monopoly board!  I had this one planned myself and then we''d both get killed for not being original.  Shadow a little harsh on the go area and some fringing on the letters.</td>', 'Wow... glad I didn''t find our monopoly board!  I had this one planned myself and then we''d both get killed for not being original.  Shadow a little harsh on the go area and some fringing on the letters.', '2009-02-04 00:08:34.000000', NULL, 1),
(5238133, 762075, 49954, '<td valign="top">But the chicken came first. :)</td>', 'But the chicken came first. :)', '2009-02-04 00:08:55.000000', NULL, 1),
(5238244, 762411, 24870, '<td valign="top">Wish it was a bit bigger! But really nice.. 8</td>', 'Wish it was a bit bigger! But really nice.. 8', '2009-02-04 00:36:53.000000', NULL, 1),
(5238285, 762229, 96881, '<td valign="top">As a Blackburn Rovers Supporter, I must mark you down for the Liverpool Shirt............<br/> <br/>Nice Expression.  Would have been great with some lighting from abpve to just stop her hair from merging with the black backdrop.  I like to contrast of Red on Black, which makes the rest of her stand out well from the background.<br/>The light appears to be from directly in front (correct me if I am wrong).  This causes the areas closest to the camera and directly in front (her Arms, the Carlsberg logo) to grab a little too much attention, rather than her face, which appears slightly darker.  I would love my eyes to get drawn to the face more than the arms in this shot.</td>', 'As a Blackburn Rovers Supporter, I must mark you down for the Liverpool Shirt............ Nice Expression.  Would have been great with some lighting from abpve to just stop her hair from merging with the black backdrop.  I like to contrast of Red on Black, which makes the rest of her stand out well from the background.The light appears to be from directly in front (correct me if I am wrong).  This causes the areas closest to the camera and directly in front (her Arms, the Carlsberg logo) to grab a little too much attention, rather than her face, which appears slightly darker.  I would love my eyes to get drawn to the face more than the arms in this shot.', '2009-02-04 00:51:26.000000', NULL, 1),
(5238376, 762522, 94601, '<td valign="top">exposure of the door/ground/walls is good- but looks a bit blown out on the foreground subject.  Great use of a close subject to give the perception of a massive size difference (with a title to match).  A slow sync flash a longer exposure could have helped balance out the lighting in this one.</td>', 'exposure of the door/ground/walls is good- but looks a bit blown out on the foreground subject.  Great use of a close subject to give the perception of a massive size difference (with a title to match).  A slow sync flash a longer exposure could have helped balance out the lighting in this one.', '2009-02-04 02:14:41.000000', NULL, 1),
(5238379, 760894, 94601, '<td valign="top">I think Chicken. =o)<br/> <br/>I like the texture on the egg and I love the background.  It''s a simple texture, not overpowering, but adds a lot.  Would have been nice to not have the shadow in both the bottom corners.</td>', 'I think Chicken. =o) I like the texture on the egg and I love the background.  It''s a simple texture, not overpowering, but adds a lot.  Would have been nice to not have the shadow in both the bottom corners.', '2009-02-04 02:16:40.000000', NULL, 1),
(5238380, 762596, 102416, '<td valign="top">FANTASTIC</td>', 'FANTASTIC', '2009-02-04 02:17:21.000000', NULL, 1),
(5238381, 762493, 94601, '<td valign="top">Looks like the beginning of a great trip.  It''s a nice shot- looks like it''d be a small corner photo in a hiking magazine. No real complaints, well lit, composed, great colors.  Not completely unique or original, but a nice idea.  Well done.</td>', 'Looks like the beginning of a great trip.  It''s a nice shot- looks like it''d be a small corner photo in a hiking magazine. No real complaints, well lit, composed, great colors.  Not completely unique or original, but a nice idea.  Well done.', '2009-02-04 02:18:40.000000', NULL, 1),
(5238384, 762501, 94601, '<td valign="top">Nice.  I love the blue sky with the golden/red tint on the fog- it just screams daybreak.  Could have possible cropped a bit more off of the top and bottom (maybe knocked out the white at the bottom right so there''s more contrast from the shadow to the main subject).  Very cool capture (literally!... budum dum chingggg- bad pun- sorry).</td>', 'Nice.  I love the blue sky with the golden/red tint on the fog- it just screams daybreak.  Could have possible cropped a bit more off of the top and bottom (maybe knocked out the white at the bottom right so there''s more contrast from the shadow to the main subject).  Very cool capture (literally!... budum dum chingggg- bad pun- sorry).', '2009-02-04 02:21:20.000000', NULL, 1),
(5238386, 762112, 94601, '<td valign="top">Great idea... great shallow DOF... I like the lighting a lot- there''s quite a bit of character in the white spaces of the pages- instead of being all white and washed out... there''s a nice quiet/soft life to it.  Good job on the border too!  My voting just started, but this is the first one that jumped out to me.  Very well done!</td>', 'Great idea... great shallow DOF... I like the lighting a lot- there''s quite a bit of character in the white spaces of the pages- instead of being all white and washed out... there''s a nice quiet/soft life to it.  Good job on the border too!  My voting just started, but this is the first one that jumped out to me.  Very well done!', '2009-02-04 02:22:57.000000', NULL, 1),
(5238388, 762203, 94601, '<td valign="top">Very pretty shot.  I''m sure it looked great in person.    I think the framing and lighting on this shot are both well done.  The focus is a bit misplaced- the center branch midway up is quite sharp and all of the blossoms are soft.  The focus could have been set right at first, and a windy day would have blown it right out of focus... or if you were using autofocus, your camera may have just focused on the center of the shot.  If you can capture this again with the blossoms in focus, it could be great!</td>', 'Very pretty shot.  I''m sure it looked great in person.    I think the framing and lighting on this shot are both well done.  The focus is a bit misplaced- the center branch midway up is quite sharp and all of the blossoms are soft.  The focus could have been set right at first, and a windy day would have blown it right out of focus... or if you were using autofocus, your camera may have just focused on the center of the shot.  If you can capture this again with the blossoms in focus, it could be great!', '2009-02-04 02:25:44.000000', NULL, 1),
(5238389, 762112, 102429, '<td valign="top">I like how you chose to take a picture of the first chapter of a book, but I think that you could have taken the picture at another angle so that it is not too blurry.</td>', 'I like how you chose to take a picture of the first chapter of a book, but I think that you could have taken the picture at another angle so that it is not too blurry.', '2009-02-04 02:26:28.000000', NULL, 1),
(5238392, 761681, 102429, '<td valign="top">This is a very interesting picture of a rose.</td>', 'This is a very interesting picture of a rose.', '2009-02-04 02:27:01.000000', NULL, 1),
(5238395, 762488, 94601, '<td valign="top">The exposure on the egg is nice- clean background. I think the jigger (or whatever using to hold the egg) caught the light a bit too much and takes the focus away from the egg- plus it''s size is dominating compared to the egg too.  The title makes me think the egg is supposed to be the main part of the shot?<br/> <br/>All in all, clean shot. Keep it up!</td>', 'The exposure on the egg is nice- clean background. I think the jigger (or whatever using to hold the egg) caught the light a bit too much and takes the focus away from the egg- plus it''s size is dominating compared to the egg too.  The title makes me think the egg is supposed to be the main part of the shot? All in all, clean shot. Keep it up!', '2009-02-04 02:28:09.000000', NULL, 1),
(5238396, 762407, 94601, '<td valign="top">Fantastic shot.  I love that both eyes are both so penetrating, sharp, and inquisitive.  Just enough of the camera and hands to tell a story, but not too much to cloud the shot.  I love the lighting and the shadow- makes it look real and not overly lit in a studio.  This is a perfect shot IMO- couldn''t ask for anything more.</td>', 'Fantastic shot.  I love that both eyes are both so penetrating, sharp, and inquisitive.  Just enough of the camera and hands to tell a story, but not too much to cloud the shot.  I love the lighting and the shadow- makes it look real and not overly lit in a studio.  This is a perfect shot IMO- couldn''t ask for anything more.', '2009-02-04 02:30:14.000000', NULL, 1),
(5238397, 760507, 102429, '<td valign="top">I like how this picture is almost like an illusion because you have to look carefully to actually see the animals and people.</td>', 'I like how this picture is almost like an illusion because you have to look carefully to actually see the animals and people.', '2009-02-04 02:30:25.000000', NULL, 1),
(5238401, 762552, 94601, '<td valign="top">Nice shallow DOF.  Great color and lighting.  The bottom of the frame is a bit busy... could possibly be cropped out?  Let the bottom of the shot be right where the sprout breaks the ground- that way there''s less to distract the eye from a crisp and colorful soon to be... flower?</td>', 'Nice shallow DOF.  Great color and lighting.  The bottom of the frame is a bit busy... could possibly be cropped out?  Let the bottom of the shot be right where the sprout breaks the ground- that way there''s less to distract the eye from a crisp and colorful soon to be... flower?', '2009-02-04 02:32:11.000000', NULL, 1),
(5238402, 761272, 94601, '<td valign="top">That is fantastic detail, and even some nice eye contact with a seductive look of the shoulder.  The title pulls it in enough to make it fit the challenge =o) Creative, so I''ll give it to you! haha.  I think this is a fantastic photo- I just wish that stem wasn''t popping up in the back- but wouldn''t crop it out because I like the space up there.  Something to fix with advanced editing outside of this challenge. 8 from me!</td>', 'That is fantastic detail, and even some nice eye contact with a seductive look of the shoulder.  The title pulls it in enough to make it fit the challenge =o) Creative, so I''ll give it to you! haha.  I think this is a fantastic photo- I just wish that stem wasn''t popping up in the back- but wouldn''t crop it out because I like the space up there.  Something to fix with advanced editing outside of this challenge. 8 from me!', '2009-02-04 02:34:23.000000', NULL, 1),
(5238403, 762454, 94601, '<td valign="top">Ah, isn''t it ironic that it''s titled "from the BEGINNING" and yet it''s track 4 in the playlist? haha.  It''s a nice product shot of the Ipod-  I''m not a fan of the highlight (i''m assuming reflection?) at the bottom of the frame.  It''s nice... and original, but not overly creative.</td>', 'Ah, isn''t it ironic that it''s titled "from the BEGINNING" and yet it''s track 4 in the playlist? haha.  It''s a nice product shot of the Ipod-  I''m not a fan of the highlight (i''m assuming reflection?) at the bottom of the frame.  It''s nice... and original, but not overly creative.', '2009-02-04 02:36:40.000000', NULL, 1),
(5238405, 760951, 94601, '<td valign="top">Looks delicious!  It''s a pretty complete shot IMO.  The one thing that I would want in this is just a little tiny bit more in depth of field.  I''d love to see more detail in the faces of the orange slices- sharper spokes, even sharper reflections- so the whole plate is in focus.  It is definitely making me think of breakfast tomorrow!</td>', 'Looks delicious!  It''s a pretty complete shot IMO.  The one thing that I would want in this is just a little tiny bit more in depth of field.  I''d love to see more detail in the faces of the orange slices- sharper spokes, even sharper reflections- so the whole plate is in focus.  It is definitely making me think of breakfast tomorrow!', '2009-02-04 02:38:27.000000', NULL, 1),
(5238406, 762505, 94601, '<td valign="top">Interesting.  Great lines and shape.  It would have been great if you could have found the end of the fence line, or even a corner to portray more "beginning" feelings- this feels like the middle of a walk to me because of the feeling that I''m in the middle of the fence line.<br/> <br/>Shot wise outside of that, it''s great.  I think the lack of definition from the ground to sky really works well with the fence being the only thing that helps the eye separate the two.  Keep up the good work!</td>', 'Interesting.  Great lines and shape.  It would have been great if you could have found the end of the fence line, or even a corner to portray more "beginning" feelings- this feels like the middle of a walk to me because of the feeling that I''m in the middle of the fence line. Shot wise outside of that, it''s great.  I think the lack of definition from the ground to sky really works well with the fence being the only thing that helps the eye separate the two.  Keep up the good work!', '2009-02-04 02:40:24.000000', NULL, 1),
(5238409, 762599, 79806, '<td valign="top">This one stood out because of the new life and the watch put together - haven''t seen that before - very effective.</td>', 'This one stood out because of the new life and the watch put together - haven''t seen that before - very effective.', '2009-02-04 02:43:18.000000', NULL, 1),
(5238410, 761732, 94601, '<td valign="top">Love the idea!  It took me a second to get what was going on because first my eyes were drawn to the mom''s legs on the right (brightest) then to the dad''s on the left (sharpest, most defined and in the foreground) then to the baby''s- which is the farthest away and in the shadow.  Maybe if the shadow wasn''t angled, things would have popped a bit more?<br/> <br/>Other than that, I love the detail in the sand and on dad''s shoes.  I would like to see just a bit deeper blacks/greys in the shadow- it feels a bit over lightened to me.  But this has to be my favorite concept so far.  Definitely made me smile.</td>', 'Love the idea!  It took me a second to get what was going on because first my eyes were drawn to the mom''s legs on the right (brightest) then to the dad''s on the left (sharpest, most defined and in the foreground) then to the baby''s- which is the farthest away and in the shadow.  Maybe if the shadow wasn''t angled, things would have popped a bit more? Other than that, I love the detail in the sand and on dad''s shoes.  I would like to see just a bit deeper blacks/greys in the shadow- it feels a bit over lightened to me.  But this has to be my favorite concept so far.  Definitely made me smile.', '2009-02-04 02:43:24.000000', NULL, 1),
(5238413, 760508, 94601, '<td valign="top">Wow, this couple moves fast! haha.  Is it really a new friendship or are they old friends?  I''m a dog person and I don''t see a lot of loving introductions with cats.<br/> <br/>The shot itself is great.  The detail in the wood is fantastic, and the cats eyes are the first thing that I saw.  If you can edit out that blue on the right, my eyes would be well focused on the dog/cat love going on.  Overall, nice shot.</td>', 'Wow, this couple moves fast! haha.  Is it really a new friendship or are they old friends?  I''m a dog person and I don''t see a lot of loving introductions with cats. The shot itself is great.  The detail in the wood is fantastic, and the cats eyes are the first thing that I saw.  If you can edit out that blue on the right, my eyes would be well focused on the dog/cat love going on.  Overall, nice shot.', '2009-02-04 02:45:36.000000', NULL, 1),
(5238417, 761738, 94601, '<td valign="top">Great way to utilize pattern and shallow depth of field.  I hope you got it in just a few takes- or else there could be a lot of matches used!  I am always a fan of grainy shots- the wood looks fantastic and textured, and the grain in the first match head helps it look like it''s just ready to explode.  Nice touch with the border.  It''s a complete shot- can''t really offer up any constructive criticism.</td>', 'Great way to utilize pattern and shallow depth of field.  I hope you got it in just a few takes- or else there could be a lot of matches used!  I am always a fan of grainy shots- the wood looks fantastic and textured, and the grain in the first match head helps it look like it''s just ready to explode.  Nice touch with the border.  It''s a complete shot- can''t really offer up any constructive criticism.', '2009-02-04 02:48:02.000000', NULL, 1),
(5238419, 760545, 94601, '<td valign="top">I''m not sure how MIDnight expresses "Begin"<br/> <br/>In regards to the shot, it''s a bit noisy and there focus is soft... there doesn''t seem to be anything that demands my eyes'' attention.  If this was a handheld shot, a tripod could really help with the long exposure.<br/> <br/>On a good note- I think the exposure itself is nice- you got a great silhouette of a tree- I just wish it was a sharper one.  Keep trying, you''re on the right track!</td>', 'I''m not sure how MIDnight expresses "Begin" In regards to the shot, it''s a bit noisy and there focus is soft... there doesn''t seem to be anything that demands my eyes'' attention.  If this was a handheld shot, a tripod could really help with the long exposure. On a good note- I think the exposure itself is nice- you got a great silhouette of a tree- I just wish it was a sharper one.  Keep trying, you''re on the right track!', '2009-02-04 02:50:25.000000', NULL, 1),
(5238421, 760883, 5364, '<td valign="top">why such a small image? it''s almost impossible to make out what you have photographed, which is a pity because as far as I can tell you''ve got a good subject.</td>', 'why such a small image? it''s almost impossible to make out what you have photographed, which is a pity because as far as I can tell you''ve got a good subject.', '2009-02-04 02:51:46.000000', NULL, 1),
(5238422, 762438, 94601, '<td valign="top">Great silhouettes and color.  Not sure how you captured it, but I love the fact that the sky made a natural gradient for you from a deep strong blue to a light tropical blue.  Very nice.</td>', 'Great silhouettes and color.  Not sure how you captured it, but I love the fact that the sky made a natural gradient for you from a deep strong blue to a light tropical blue.  Very nice.', '2009-02-04 02:51:47.000000', NULL, 1),
(5238427, 761002, 94601, '<td valign="top">nice capture.  I know it''s hard at this close of a shot/macro- but the 1st bloom that is being harvested is such a pretty one up close, I would have loved for the whole shot to be in focus.  I don''t know if that''d be possible to capture with a smaller aperture (maybe the shutter would have been to slow).  It''s a great capture though.  Well done.</td>', 'nice capture.  I know it''s hard at this close of a shot/macro- but the 1st bloom that is being harvested is such a pretty one up close, I would have loved for the whole shot to be in focus.  I don''t know if that''d be possible to capture with a smaller aperture (maybe the shutter would have been to slow).  It''s a great capture though.  Well done.', '2009-02-04 02:54:21.000000', NULL, 1),
(5238504, 762083, 94601, '<td valign="top">Great photo. Was that actually written? (Looks printed to me)- I think you have a lot of things that really work here... especially fanning out the paper (which someone writing a story would probably square up instead)- great exposure, great contrast, well lit hand.  Very nice shot.</td>', 'Great photo. Was that actually written? (Looks printed to me)- I think you have a lot of things that really work here... especially fanning out the paper (which someone writing a story would probably square up instead)- great exposure, great contrast, well lit hand.  Very nice shot.', '2009-02-04 04:03:19.000000', NULL, 1),
(5238510, 761873, 94601, '<td valign="top">haha. funny shot.  The sandwich itself looks fantastic- well lit, great color- the sky looks great too.  But it leaves the sandwich eater looking a bit snap shot ish- the huge shadow across the majority of his face, but his forehead and neck being so well lit pulls they eye away from where you would want it to be.  A fill flash from your camera would have done wonders for this shot.<br/> <br/>In terms of creativity great shot!  Execution was ok.  Looking forward to what else you come up with!</td>', 'haha. funny shot.  The sandwich itself looks fantastic- well lit, great color- the sky looks great too.  But it leaves the sandwich eater looking a bit snap shot ish- the huge shadow across the majority of his face, but his forehead and neck being so well lit pulls they eye away from where you would want it to be.  A fill flash from your camera would have done wonders for this shot. In terms of creativity great shot!  Execution was ok.  Looking forward to what else you come up with!', '2009-02-04 04:05:42.000000', NULL, 1),
(5238514, 762354, 94601, '<td valign="top">First of all, I think this is a great photo.  The statues look fantastic and have quite a bit of character beyond the figurines themselves- the lighting and shadows are great and add quite a bit.  Great background gives fantastic pop to the shot, but is in the right color palette to enhance the browns in the dancers.<br/> <br/>Outside of the title though, this doesn''t look like a beginning of something (certainly doesn''t look like the beginning of a dance- looks a lot more like the big ending!)  So I do think you''re stretching it a bit, but I also think it''s a fantastic shot... so all in all this averages out to 5/6 range for me- even though I wish I could give it more.</td>', 'First of all, I think this is a great photo.  The statues look fantastic and have quite a bit of character beyond the figurines themselves- the lighting and shadows are great and add quite a bit.  Great background gives fantastic pop to the shot, but is in the right color palette to enhance the browns in the dancers. Outside of the title though, this doesn''t look like a beginning of something (certainly doesn''t look like the beginning of a dance- looks a lot more like the big ending!)  So I do think you''re stretching it a bit, but I also think it''s a fantastic shot... so all in all this averages out to 5/6 range for me- even though I wish I could give it more.', '2009-02-04 04:09:26.000000', NULL, 1),
(5238516, 762661, 94601, '<td valign="top">This shot brings a really interesting perspective.  Is this a real landscape?  It looks a lot like the trees from the old animated frosty the snowman movies.  I love it.  The dark sky in the top right brings a nice contrast to the trees as well as the bright sky on the left.<br/> <br/>I''m waiting for the singing to begin! Well done.</td>', 'This shot brings a really interesting perspective.  Is this a real landscape?  It looks a lot like the trees from the old animated frosty the snowman movies.  I love it.  The dark sky in the top right brings a nice contrast to the trees as well as the bright sky on the left. I''m waiting for the singing to begin! Well done.', '2009-02-04 04:11:04.000000', NULL, 1),
(5238579, 762150, 103454, '<td valign="top">I love the details, the drop and ripple.</td>', 'I love the details, the drop and ripple.', '2009-02-04 05:49:18.000000', NULL, 1),
(5238583, 762424, 98186, '<td valign="top">Nice picture.  I didn''t realize that it was a coffee maker until I saw "BREW".  I think it would be cool if you used a larger DOF and had some coffee already poured in that white mug.</td>', 'Nice picture.  I didn''t realize that it was a coffee maker until I saw "BREW".  I think it would be cool if you used a larger DOF and had some coffee already poured in that white mug.', '2009-02-04 05:56:06.000000', NULL, 1),
(5238585, 762161, 98186, '<td valign="top">Very creative in my opinion.  The chicken feet make it humorous :)</td>', 'Very creative in my opinion.  The chicken feet make it humorous :)', '2009-02-04 05:57:29.000000', NULL, 1),
(5238588, 762073, 98186, '<td valign="top">I like your idea.  Too much white space for my tastes.  I would like a shot like this if it were taken in a coffee shop or at a business meeting.</td>', 'I like your idea.  Too much white space for my tastes.  I would like a shot like this if it were taken in a coffee shop or at a business meeting.', '2009-02-04 06:02:04.000000', NULL, 1),
(5238595, 762533, 98186, '<td valign="top">Funny and creative.  One of a kind :)</td>', 'Funny and creative.  One of a kind :)', '2009-02-04 06:13:22.000000', NULL, 1),
(5238596, 762532, 42181, '<td valign="top">Looks like the start of a great walk</td>', 'Looks like the start of a great walk', '2009-02-04 06:18:01.000000', NULL, 1),
(5238598, 762506, 42181, '<td valign="top">OK, how the hell did you get this picture???? Great looking shot and hits the challenge spot on.</td>', 'OK, how the hell did you get this picture???? Great looking shot and hits the challenge spot on.', '2009-02-04 06:19:19.000000', NULL, 1),
(5238601, 760528, 42181, '<td valign="top">Great looking macro shot, perfect challenge shot. I particularly like ferns.</td>', 'Great looking macro shot, perfect challenge shot. I particularly like ferns.', '2009-02-04 06:23:10.000000', NULL, 1),
(5238607, 762664, 42181, '<td valign="top">Good looking shot with pin point focus, I''m not so sure about the background.</td>', 'Good looking shot with pin point focus, I''m not so sure about the background.', '2009-02-04 06:25:09.000000', NULL, 1),
(5238613, 762377, 42181, '<td valign="top">Great idea, love the design drawing. Good lighting, very cool.</td>', 'Great idea, love the design drawing. Good lighting, very cool.', '2009-02-04 06:32:58.000000', NULL, 1),
(5238617, 761218, 47294, '<td valign="top">I love her expression, I also love the leading lines and the vaishing point...magic natural desat! 9</td>', 'I love her expression, I also love the leading lines and the vaishing point...magic natural desat! 9', '2009-02-04 06:35:30.000000', NULL, 1),
(5238642, 762150, 103455, '<td valign="top">Stunning!</td>', 'Stunning!', '2009-02-04 06:54:20.000000', NULL, 1),
(5238663, 760951, 103069, '<td valign="top">Nice photo, I do feel you have captured the beginning.  Good Luck.  This is my 10</td>', 'Nice photo, I do feel you have captured the beginning.  Good Luck.  This is my 10', '2009-02-04 07:14:00.000000', NULL, 1),
(5238664, 761957, 103069, '<td valign="top">Very nice capture. Truly the beginning.</td>', 'Very nice capture. Truly the beginning.', '2009-02-04 07:14:28.000000', NULL, 1),
